from Bio.PDB import PDBParser, ShrakeRupley, NeighborSearch
from Bio.PDB.Polypeptide import is_aa
from Bio.SeqUtils import seq1
import numpy as np, copy, warnings; warnings.filterwarnings("ignore")
par=PDBParser(QUIET=True); sr=ShrakeRupley()

TPL = {"1MEL":("A","L"),"1ZVH":("A","L"),"1ZVY":("A","B"),
       "1ZV5":("A","L"),"1RI8":("A","B"),"1JTT":("A","L")}

def clean(chain):
    import Bio.PDB.Chain
    c = Bio.PDB.Chain.Chain(chain.id)
    for r in chain:
        if is_aa(r, standard=True):
            rr = r.copy()
            for a in list(rr):
                if a.element=="H": rr.detach_child(a.id)
            c.add(rr)
    return c

results={}
for pid,(vc,lc) in TPL.items():
    s=par.get_structure(pid,f"/opt/biomni/biomni/tool/data/pdb/{pid}.pdb")
    m=s[0]
    V=clean(m[vc]); L=clean(m[lc])
    # BSA via SASA on isolated vs complex
    import Bio.PDB.Model, Bio.PDB.Structure
    def sasa_of(chs):
        st=Bio.PDB.Structure.Structure("x"); mo=Bio.PDB.Model.Model(0); st.add(mo)
        for c in chs: mo.add(c.copy())
        sr.compute(mo, level="R")
        return {(c.id,r.id[1]):r.sasa for c in mo for r in c}, sum(r.sasa for c in mo for r in c)
    sV,tV=sasa_of([V]); sL,tL=sasa_of([L]); sC,tC=sasa_of([V,L])
    bsa=(tV+tL-tC)
    # interface contacts <4.5 A
    latoms=[a for r in L for a in r]; ns=NeighborSearch(latoms)
    epi={}; para={}
    for r in V:
        for a in r:
            for b in ns.search(a.coord,4.5):
                rl=b.get_parent()
                epi.setdefault(rl.id[1],set()).add(r.id[1])
                para.setdefault(r.id[1],set()).add(rl.id[1])
    # distance of VHH to catalytic Glu35 / Asp52
    def mind(resid):
        if resid not in [r.id[1] for r in L]: return None
        tgt=[a.coord for a in L[resid]]
        d=min(np.linalg.norm(a.coord-t) for r in V for a in r for t in tgt)
        return round(float(d),2)
    results[pid]=dict(bsa=bsa, epi=sorted(epi), para=sorted(para),
                      d_E35=mind(35), d_D52=mind(52),
                      epi_names={k:seq1(L[k].get_resname()) for k in sorted(epi)})
    print(f"{pid}: BSA(total)={bsa:7.1f} A^2  dBSA/side={bsa/2:6.1f}  n_epitope={len(epi):2d}  n_paratope={len(para):2d}  min d to Glu35={results[pid]['d_E35']}  Asp52={results[pid]['d_D52']}")

