def clean(ch):
    import Bio.PDB.Chain
    c=Bio.PDB.Chain.Chain(ch.id)
    for r in ch:
        if is_aa(r,standard=True):
            rr=r.copy()
            for a in list(rr):
                if a.element=="H": rr.detach_child(a.id)
            c.add(rr)
    return c
V=clean(m["A"]); L=clean(m["L"])

st=Bio.PDB.Structure.Structure("v"); mo=Bio.PDB.Model.Model(0); st.add(mo); mo.add(V.copy())
sr.compute(mo, level="R"); solo={r.id[1]:r.sasa for r in mo["A"]}

lat=[a for r in L for a in r]; ns=NeighborSearch(lat)
contact={}
for r in V:
    best=99
    for a in r:
        for b in ns.search(a.coord,8.0):
            best=min(best, float(np.linalg.norm(a.coord-b.coord)))
