"D2-L24_1ZVH":"DVQLVESGGGSVQAGGSLRLSCAASGYIASINYLGWFRQAPGKEREGVAAVSPAGGTPYYADSVKGRFTVSLDNAENTVYLQMNSLKPEDTALYYCAAARQGWYIPLNSYGYNYWGQGTQVTVS",
"D3-L11_1ZVY":"DVQLVESGGGSVQAGGSLRLSCAASGSTDSIEYMTWFRQAPGKAREGVAALYTHTGNTYYTDSVKGRFTISQDKAKNMAYLRMDSVKSEDTAIYTCGATRKYVPVRFALDQSSYDYWGQGTQVTV",
"D2-L29_1ZV5":"VQLVESGGGSVQAGESLRLSCAASGVTYKNYCIGWFRQAPGKDREGVVFINSDGGITYYADSVKGRFTISQDNAKNTVYLQMNSLKPEDTASYYCAAGYRNYGQCATRYWGQGTQVTVS",
"D2-L19_1RI8":"VQLVESGGGSVQAGGSLRLSCAVSGYKDRNYCMGWFRRAPGKEREGVAVIDSSGRTAYADSVKGRFTISRDVALDTAYLQMNSLKPEDTAMYYCAAGWSSLGSCGTNRNRYNYWGQGTQVTVSS",
}
al=Align.PairwiseAligner(); al.substitution_matrix=substitution_matrices.load("BLOSUM62")
al.open_gap_score=-11; al.extend_gap_score=-1; al.mode="global"
ref=vhh["cAb-Lys3_1MEL"]
cols={}
for name,sq in vhh.items():
    if name=="cAb-Lys3_1MEL": 
        for k,c in enumerate(ref): cols.setdefault(k,[]).append(c)
        continue
    aln=al.align(ref,sq)[0]
    a,b=aln[0],aln[1]
